import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class HardwareR8PolicyTest{@Test void fixedNamesBindStrategies(){assertEquals(0,HardwareBackendRuntime.policyFor("rt-aabb"));assertEquals(1,HardwareBackendRuntime.policyFor("rt-aabb-r8-merged"));assertEquals(2,HardwareBackendRuntime.policyFor("rt-aabb-r8-event"));assertEquals(4,HardwareBackendRuntime.policyFor("rt-triangle-r8-paged"));assertEquals(8,HardwareBackendRuntime.policyFor("rt-aabb-r8-unsorted"));assertEquals(16,HardwareBackendRuntime.policyFor("rt-aabb-r8-gl-dome"));assertEquals(7,HardwareBackendRuntime.policyFor("rt-aabb-r8-combined"));assertEquals(12,HardwareBackendRuntime.policyFor("rt-aabb-r8-paged-unsorted"));assertEquals(15,HardwareBackendRuntime.policyFor("rt-aabb-r8-combined-unsorted"));assertEquals(1,HardwareBackendRuntime.primitiveFor("rt-aabb-r8-combined"));assertEquals(2,HardwareBackendRuntime.primitiveFor("rt-triangle-r8-paged"));assertEquals(0,HardwareBackendRuntime.primitiveFor("cuda-control-r8-paged"));assertThrows(IllegalArgumentException.class,()->HardwareBackendRuntime.policyFor("rt-aabb-r8-unknown"));}@Test void productionDiagnosticsDoNotInventNativeState(){String value=HardwareBackendRuntime.INSTANCE.description();assertTrue(value.contains("query=production-gl"));assertTrue(value.contains("dome=production-gl"));assertTrue(value.contains("native_abi=unavailable"));assertEquals("unavailable",HardwareNative.digest());}}
